import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        List<String[]> rows = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            rows.add(sc.nextLine().trim().split("\\s+"));
        }

        Map<String, Integer> effort = new LinkedHashMap<>();
        Map<String, String> name = new LinkedHashMap<>();
        for (String[] row : rows) {
            name.put(row[0], row[1]);
            effort.put(row[0], Integer.parseInt(row[2]));
        }

        List<String> problems = new ArrayList<>();
        int leafTotal = 0;
        for (String number : effort.keySet()) {
            int childSum = 0;
            boolean hasChild = false;
            for (String other : effort.keySet()) {
                if (isChild(number, other)) {
                    hasChild = true;
                    childSum += effort.get(other);
                }
            }
            if (hasChild) {
                if (effort.get(number) != childSum) {
                    problems.add("SUM " + number + " " + effort.get(number) + " " + childSum);
                }
            } else {
                leafTotal += effort.get(number);
                if (effort.get(number) == 0) {
                    problems.add("ZERO " + number + " " + name.get(number));
                }
            }
        }
        problems.sort(Comparator.comparing(line -> line.split(" ")[1]));

        System.out.println(problems.isEmpty() ? "OK" : "NG");
        problems.forEach(System.out::println);
        System.out.println("合計 " + leafTotal);
    }

    /** child が parent の直接の子か（間に階層を挟まないか）。 */
    static boolean isChild(String parent, String child) {
        if (!child.startsWith(parent + ".")) {
            return false;
        }
        return !child.substring(parent.length() + 1).contains(".");
    }
}

