public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        double pv = 0;
        double ev = 0;
        double ac = 0;
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            int planned = Integer.parseInt(parts[1]);
            int plannedRate = Integer.parseInt(parts[2]);
            int actualRate = Integer.parseInt(parts[3]);
            pv += planned * plannedRate / 100.0;
            ev += planned * actualRate / 100.0;
            ac += Integer.parseInt(parts[4]);
        }
        double spi = ev / pv;
        double cpi = ev / ac;
        System.out.printf("PV %.1f%n", pv);
        System.out.printf("EV %.1f%n", ev);
        System.out.printf("AC %.1f%n", ac);
        System.out.printf("SPI %.2f%n", spi);
        System.out.printf("CPI %.2f%n", cpi);
        System.out.println("判定 " + (spi < 1 ? "遅れ" : "予定どおり")
                + " " + (cpi < 1 ? "超過" : "予算内"));
    }
}

