public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        List<String[]> risks = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            risks.add(sc.nextLine().trim().split("\\s+"));
        }

        risks.sort((a, b) -> {
            int scoreA = Integer.parseInt(a[1]) * Integer.parseInt(a[2]);
            int scoreB = Integer.parseInt(b[1]) * Integer.parseInt(b[2]);
            return scoreA != scoreB ? Integer.compare(scoreB, scoreA) : a[0].compareTo(b[0]);
        });

        int key = 0;
        List<String> open = new ArrayList<>();
        for (String[] risk : risks) {
            int score = Integer.parseInt(risk[1]) * Integer.parseInt(risk[2]);
            System.out.println(risk[0] + " " + score + " " + risk[3]);
            if (score >= 12) {
                key++;
                if (risk[3].equals("未定")) {
                    open.add(risk[0]);
                }
            }
        }
        for (String id : open) {
            System.out.println("未対応 " + id);
        }
        System.out.println("重点 " + key + " 未対応 " + open.size());
    }
}

