import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        LocalDate today = LocalDate.parse(sc.nextLine().trim());
        int n = Integer.parseInt(sc.nextLine().trim());
        List<String[]> issues = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            issues.add(sc.nextLine().trim().split("\\s+"));
        }
        issues.sort(Comparator.comparing(issue -> issue[0]));

        int unassigned = 0;
        int late = 0;
        for (String[] issue : issues) {
            if (issue[3].equals("完了")) {
                continue;
            }
            StringBuilder line = new StringBuilder(issue[0]);
            boolean noOwner = issue[1].equals("-");
            long days = ChronoUnit.DAYS.between(LocalDate.parse(issue[2]), today);
            if (noOwner) {
                unassigned++;
                line.append(" 担当未定");
            }
            if (days > 0) {
                late++;
                line.append(" 遅延 ").append(days).append("日");
            }
            if (!noOwner && days <= 0) {
                line.append(" ok");
            }
            System.out.println(line);
        }
        System.out.println("担当未定 " + unassigned + " 遅延 " + late);
    }
}

