import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        Map<String, Double> byParent = new TreeMap<>();
        double expectedTotal = 0;
        double varianceTotal = 0;
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            String parent = parts[0].substring(0, parts[0].indexOf('.'));
            int o = Integer.parseInt(parts[2]);
            int m = Integer.parseInt(parts[3]);
            int p = Integer.parseInt(parts[4]);
            double expected = (o + 4.0 * m + p) / 6;
            double deviation = (p - o) / 6.0;
            byParent.merge(parent, expected, Double::sum);
            expectedTotal += expected;
            varianceTotal += deviation * deviation;
        }
        for (Map.Entry<String, Double> entry : byParent.entrySet()) {
            System.out.printf("%s %.1f%n", entry.getKey(), entry.getValue());
        }
        double whole = Math.sqrt(varianceTotal);
        System.out.printf("合計 %.1f%n", expectedTotal);
        System.out.printf("ばらつき %.1f%n", whole);
        System.out.printf("目安 %.1f%n", expectedTotal + whole);
    }
}

