import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        double pvTotal = 0;
        double evTotal = 0;
        List<Object[]> behind = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            int planned = Integer.parseInt(parts[1]);
            double pv = planned * Integer.parseInt(parts[2]) / 100.0;
            double ev = planned * Integer.parseInt(parts[3]) / 100.0;
            pvTotal += pv;
            evTotal += ev;
            if (pv > ev) {
                behind.add(new Object[] {parts[0], pv - ev});
            }
        }
        behind.sort(Comparator.comparingDouble((Object[] row) -> -(double) row[1])
                .thenComparing(row -> (String) row[0]));

        System.out.printf("SPI %.2f%n", evTotal / pvTotal);
        double delaySum = 0;
        for (Object[] row : behind) {
            System.out.printf("%s %.1f%n", row[0], (double) row[1]);
            delaySum += (double) row[1];
        }
        System.out.printf("遅れ合計 %.1f%n", delaySum);
    }
}
